// Lexique de l'e-commerce : une page par mot (/lexique/<mot>), définition simple, exemple et conseil.
// Définitions générales et vérifiables, sans chiffre inventé.
export type Term = { term: string; def: string; example: string; tip: string; related?: string[] };

export const GLOSSARY: Term[] = [
  { term: "Dropshipping", def: "Méthode de vente en ligne où le vendeur ne garde pas de stock : quand un client commande, le fournisseur envoie le produit directement au client.", example: "Tu vends une lampe sur ta boutique, et ton fournisseur l'expédie à ton client.", tip: "Commande toujours un échantillon avant de vendre, pour vérifier la qualité et le délai réel.", related: ["Fournisseur", "Délai de livraison", "Marge"] },
  { term: "Boutique en ligne", def: "Site internet qui permet de présenter des produits, de recevoir des commandes et d'encaisser des paiements.", example: "Une boutique Shopify avec une page d'accueil, des fiches produit et un panier.", tip: "Une boutique simple et claire vend souvent mieux qu'une boutique chargée.", related: ["Shopify", "Fiche produit", "Panier"] },
  { term: "Shopify", def: "Plateforme en ligne qui permet de créer une boutique, de vendre et d'encaisser des paiements sans savoir coder, avec un abonnement mensuel.", example: "Tu choisis un thème Shopify, tu ajoutes tes produits et tu publies ta boutique.", tip: "Vérifie toujours les tarifs à jour sur le site de Shopify avant de te lancer.", related: ["Thème Shopify", "Boutique en ligne", "Application Shopify"] },
  { term: "Thème Shopify", def: "Modèle de design qui définit l'apparence d'une boutique Shopify : couleurs, polices, disposition des pages.", example: "Tu changes de thème pour donner un style plus élégant à ta boutique de bijoux.", tip: "Choisis un thème rapide et lisible sur téléphone : la plupart des visiteurs viennent d'un mobile.", related: ["Shopify", "Page d'accueil"] },
  { term: "Application Shopify", def: "Outil qu'on ajoute à une boutique Shopify pour lui donner une fonction en plus : avis clients, e-mails, dropshipping, etc.", example: "Une application qui affiche les avis de tes clients sur la fiche produit.", tip: "N'installe que les applications utiles : elles peuvent ralentir la boutique et s'additionner en coût.", related: ["Shopify", "Avis clients"] },
  { term: "Fiche produit", def: "Page qui présente un produit : photos, description, prix, options, délais de livraison et bouton d'achat.", example: "La page de ta gourde isotherme, avec ses photos, sa contenance et son prix.", tip: "Réponds dans la fiche aux questions que se pose le client avant d'acheter.", related: ["Description produit", "Photo produit", "Taux de conversion"] },
  { term: "Description produit", def: "Texte qui explique ce que fait le produit, pour qui il est fait et pourquoi l'acheter.", example: "« Garde ta boisson fraîche toute la journée, au sport comme en cours. »", tip: "Parle des bénéfices pour le client avant les caractéristiques techniques.", related: ["Fiche produit", "Copywriting"] },
  { term: "Photo produit", def: "Image qui montre le produit sur la boutique : seul sur fond clair, en détail ou en situation.", example: "Ta lampe photographiée allumée dans une chambre le soir.", tip: "La lumière naturelle et un fond simple suffisent pour de belles photos au téléphone.", related: ["Fiche produit"] },
  { term: "Panier", def: "Espace où le client rassemble les produits qu'il veut acheter avant de payer.", example: "Le client ajoute deux coussins au panier, puis passe au paiement.", tip: "Affiche les frais de livraison avant le paiement pour éviter les mauvaises surprises.", related: ["Panier abandonné", "Panier moyen", "Checkout"] },
  { term: "Panier abandonné", def: "Panier rempli par un visiteur qui quitte la boutique sans finir son achat.", example: "Un client ajoute un produit, voit les frais de livraison et part.", tip: "Un e-mail de rappel honnête peut aider à récupérer une partie de ces ventes.", related: ["Panier", "Taux de conversion", "E-mail marketing"] },
  { term: "Panier moyen", def: "Montant moyen dépensé par commande : le chiffre d'affaires divisé par le nombre de commandes.", example: "Si tu as vendu pour 300 € en 10 commandes, ton panier moyen est de 30 €.", tip: "Les offres par lot (2 ou 3 produits) aident à augmenter le panier moyen.", related: ["Offre par lot", "Chiffre d'affaires"] },
  { term: "Checkout", def: "Page de paiement où le client entre son adresse et ses informations de paiement pour finaliser sa commande.", example: "Après le panier, le client arrive sur le checkout et paie par carte.", tip: "Plus le checkout est simple et rassurant, moins les clients abandonnent.", related: ["Panier", "Moyen de paiement"] },
  { term: "Taux de conversion", def: "Part des visiteurs qui achètent : le nombre de commandes divisé par le nombre de visites.", example: "Si 2 personnes achètent sur 100 visites, ton taux de conversion est de 2 %.", tip: "Améliore une chose à la fois (photos, texte, prix) et observe l'effet.", related: ["Visiteur", "Fiche produit", "Panier abandonné"] },
  { term: "Chiffre d'affaires", def: "Total de l'argent encaissé grâce aux ventes, avant de retirer les dépenses.", example: "Tu vends 10 produits à 30 € : ton chiffre d'affaires est de 300 €.", tip: "Ne confonds pas chiffre d'affaires et bénéfice : ce qui compte, c'est ce qui reste après les frais.", related: ["Marge", "Bénéfice"] },
  { term: "Marge", def: "Différence entre le prix de vente d'un produit et ce qu'il t'a coûté (achat, livraison, frais).", example: "Vendu 30 €, il te coûte 18 € en tout : ta marge est de 12 €.", tip: "Calcule ta marge avant de lancer de la publicité.", related: ["Bénéfice", "Prix de vente", "Coût d'acquisition"] },
  { term: "Bénéfice", def: "Ce qui reste une fois toutes les dépenses retirées du chiffre d'affaires.", example: "300 € de ventes, 220 € de dépenses : 80 € de bénéfice.", tip: "Garde une trace de toutes tes dépenses, même les petites.", related: ["Chiffre d'affaires", "Marge"] },
  { term: "Prix de vente", def: "Prix payé par le client pour un produit.", example: "Ta brosse est affichée à 34,90 € sur ta boutique.", tip: "Ton prix doit couvrir tous tes frais et te laisser une marge.", related: ["Marge", "Prix barré"] },
  { term: "Prix barré", def: "Ancien prix affiché barré à côté d'un prix réduit pour montrer une réduction.", example: "~~40 €~~ 30 €.", tip: "Le prix barré doit être un vrai prix pratiqué avant : un faux prix barré est interdit.", related: ["Prix de vente", "Code promo"] },
  { term: "Code promo", def: "Code que le client entre au paiement pour obtenir une réduction.", example: "BIENVENUE10 donne 10 % de réduction sur la première commande.", tip: "Utilise les codes promo avec modération pour ne pas habituer tes clients à attendre une réduction.", related: ["Prix barré", "E-mail marketing"] },
  { term: "Offre par lot", def: "Offre qui propose plusieurs produits ensemble à un prix avantageux.", example: "1 coussin à 25 €, ou 2 pour 45 €.", tip: "Les lots marchent bien pour les cadeaux et les produits qu'on rachète.", related: ["Panier moyen", "Upsell"] },
  { term: "Upsell", def: "Technique qui propose au client une version plus complète ou plus chère du produit qu'il regarde.", example: "Proposer la version avec batterie plus grande pour quelques euros de plus.", tip: "Propose un vrai plus, jamais une option inutile.", related: ["Cross-sell", "Panier moyen"] },
  { term: "Cross-sell", def: "Technique qui propose un produit complémentaire à celui que le client achète.", example: "Proposer des filtres de rechange avec une fontaine à eau pour chat.", tip: "Le produit proposé doit vraiment aller avec le premier.", related: ["Upsell", "Panier moyen"] },
  { term: "Fournisseur", def: "Entreprise qui fabrique ou vend en gros les produits que tu revends.", example: "Un fournisseur sur AliExpress ou un grossiste européen.", tip: "Choisis un fournisseur qui répond vite et donne des délais clairs.", related: ["Dropshipping", "Grossiste", "Échantillon"] },
  { term: "Grossiste", def: "Fournisseur qui vend des produits en grande quantité à des professionnels, à prix réduit.", example: "Tu achètes 100 gourdes à un grossiste pour les revendre.", tip: "Commence par une petite quantité si le grossiste l'accepte.", related: ["Fournisseur", "Stock"] },
  { term: "Échantillon", def: "Exemplaire du produit commandé pour le tester avant de le vendre.", example: "Tu reçois la lampe chez toi pour vérifier la qualité et prendre tes photos.", tip: "Note le délai réel de livraison de ton échantillon : c'est ce que vivront tes clients.", related: ["Fournisseur", "Photo produit"] },
  { term: "Stock", def: "Produits que le vendeur possède déjà et garde avant de les vendre.", example: "Tu as 50 colliers chez toi, prêts à être envoyés.", tip: "Commence petit pour ne pas bloquer ton argent dans des cartons.", related: ["Dropshipping", "Rupture de stock"] },
  { term: "Rupture de stock", def: "Situation où un produit n'est plus disponible à la vente.", example: "Ton produit le plus vendu n'a plus de stock chez le fournisseur.", tip: "Préviens tes clients et propose une alternative ou une date de retour.", related: ["Stock", "Fournisseur"] },
  { term: "Délai de livraison", def: "Temps entre la commande et la réception du colis par le client.", example: "Entre 7 et 12 jours ouvrés en dropshipping depuis un entrepôt lointain.", tip: "Annonce un délai honnête avant l'achat : c'est obligatoire et ça évite les remboursements.", related: ["Dropshipping", "Numéro de suivi"] },
  { term: "Numéro de suivi", def: "Code qui permet au client de suivre son colis jusqu'à la livraison.", example: "Le client reçoit un lien pour voir où est son colis.", tip: "Envoie le numéro de suivi dès qu'il est disponible pour rassurer.", related: ["Délai de livraison"] },
  { term: "Droit de rétractation", def: "Droit d'un consommateur de changer d'avis après un achat à distance, en principe pendant 14 jours en France et dans l'Union européenne, avec des exceptions.", example: "Un client renvoie une écharpe qui ne lui plaît pas dans les 14 jours.", tip: "Explique clairement les conditions dans ta politique de retour.", related: ["Politique de retour", "CGV"] },
  { term: "Politique de retour", def: "Page qui explique comment un client peut renvoyer un produit et être remboursé.", example: "Délai, adresse de retour, qui paie les frais, délai de remboursement.", tip: "Une politique claire rassure avant l'achat.", related: ["Droit de rétractation", "CGV"] },
  { term: "CGV", def: "Conditions générales de vente : document qui fixe les règles de la vente entre la boutique et ses clients.", example: "Prix, livraison, paiement, retours, garanties.", tip: "Adapte un modèle à ta situation réelle et fais-le relire en cas de doute.", related: ["Mentions légales", "Politique de retour"] },
  { term: "Mentions légales", def: "Informations obligatoires qui permettent d'identifier le responsable d'un site professionnel.", example: "Nom ou raison sociale, contact, hébergeur du site.", tip: "Vérifie les informations exigées sur un site officiel comme service-public.fr.", related: ["CGV", "Micro-entreprise"] },
  { term: "Micro-entreprise", def: "Statut simplifié en France pour exercer une activité indépendante, souvent utilisé pour démarrer une boutique en ligne.", example: "Tu déclares ton chiffre d'affaires chaque mois ou chaque trimestre.", tip: "Renseigne-toi sur les démarches officielles avant de vendre régulièrement.", related: ["Mentions légales", "Chiffre d'affaires"] },
  { term: "Moyen de paiement", def: "Façon dont le client paie : carte bancaire, portefeuille mobile, virement, etc.", example: "Carte, Apple Pay ou Google Pay sur ta boutique.", tip: "Propose les moyens de paiement que tes clients utilisent le plus.", related: ["Checkout"] },
  { term: "Visiteur", def: "Personne qui arrive sur ta boutique, depuis un réseau social, Google, une publicité ou un lien direct.", example: "Une personne qui clique sur le lien de ta bio TikTok.", tip: "Regarde d'où viennent tes visiteurs pour savoir quoi développer.", related: ["Trafic", "Taux de conversion"] },
  { term: "Trafic", def: "Ensemble des visites reçues par une boutique sur une période.", example: "300 visites cette semaine, dont la moitié depuis TikTok.", tip: "Plus de trafic ne sert à rien si la boutique ne convertit pas.", related: ["Visiteur", "SEO"] },
  { term: "SEO", def: "Référencement naturel : ensemble des actions pour apparaître dans les résultats gratuits de Google.", example: "Écrire des articles utiles sur ton sujet pour être trouvé sur Google.", tip: "Le SEO prend du temps mais apporte des visites gratuites sur la durée.", related: ["Mot-clé", "Trafic", "Sitemap"] },
  { term: "Mot-clé", def: "Mots que les gens tapent dans Google pour chercher quelque chose.", example: "« lampe coucher de soleil » ou « idée cadeau chat ».", tip: "Utilise les mots de tes clients, pas ton propre jargon.", related: ["SEO"] },
  { term: "Sitemap", def: "Fichier qui liste les pages d'un site pour aider les moteurs de recherche à les trouver.", example: "Le fichier sitemap.xml envoyé dans Google Search Console.", tip: "Envoie ton sitemap dans Search Console dès que ton site est en ligne.", related: ["SEO", "Google Search Console"] },
  { term: "Google Search Console", def: "Outil gratuit de Google qui montre comment ton site apparaît dans les recherches et quelles pages sont indexées.", example: "Tu vois sur quels mots-clés ta boutique apparaît.", tip: "Vérifie ton site dans Search Console dès le début.", related: ["SEO", "Sitemap", "Indexation"] },
  { term: "Indexation", def: "Moment où Google enregistre une page dans son index, ce qui lui permet ensuite de l'afficher dans les résultats.", example: "Ta nouvelle page produit apparaît sur Google quelques jours après sa publication.", tip: "C'est Google qui décide : des pages utiles et un sitemap envoyé l'aident à indexer.", related: ["SEO", "Sitemap"] },
  { term: "Publicité Meta", def: "Publicité payante diffusée sur Facebook et Instagram.", example: "Une vidéo de ton produit montrée à des personnes intéressées par la déco.", tip: "Lance la publicité seulement quand ta boutique convertit déjà un peu.", related: ["Coût d'acquisition", "Retargeting"] },
  { term: "Coût d'acquisition", def: "Ce que te coûte en moyenne l'obtention d'un client (publicité, cadeaux, temps).", example: "100 € de pub pour 5 ventes : 20 € par client.", tip: "Ton coût d'acquisition doit rester inférieur à ta marge.", related: ["Marge", "Publicité Meta"] },
  { term: "Retargeting", def: "Publicité montrée aux personnes qui ont déjà visité ta boutique sans acheter.", example: "Un visiteur voit à nouveau ton produit sur Instagram le lendemain.", tip: "Respecte les règles sur les cookies et le consentement des visiteurs.", related: ["Publicité Meta", "Panier abandonné"] },
  { term: "E-mail marketing", def: "Envoi d'e-mails à tes clients ou prospects pour les informer, les relancer ou leur proposer des offres.", example: "Un e-mail pour annoncer un nouveau produit.", tip: "N'écris qu'aux personnes qui ont accepté de recevoir tes e-mails.", related: ["Panier abandonné", "Newsletter"] },
  { term: "Newsletter", def: "E-mail envoyé régulièrement à une liste d'abonnés.", example: "Une lettre par mois avec tes nouveautés et un conseil.", tip: "Apporte de la valeur à chaque envoi, pas seulement des promotions.", related: ["E-mail marketing"] },
  { term: "Avis clients", def: "Retours écrits par les clients sur un produit ou une boutique.", example: "« Reçu en 8 jours, très joli dans ma chambre. »", tip: "Les faux avis sont interdits : demande de vrais avis après la livraison.", related: ["Preuve sociale", "Fiche produit"] },
  { term: "Preuve sociale", def: "Éléments qui montrent que d'autres personnes font confiance à une boutique : avis, photos de clients, mentions.", example: "Des photos envoyées par tes clients sur la fiche produit.", tip: "N'utilise que des preuves vraies et vérifiables.", related: ["Avis clients"] },
  { term: "UGC", def: "Contenu créé par les utilisateurs : photos ou vidéos de ton produit faites par tes clients ou des créateurs.", example: "Une cliente filme son déballage et te permet de la partager.", tip: "Demande toujours l'autorisation avant de réutiliser un contenu.", related: ["Preuve sociale", "Influenceur"] },
  { term: "Influenceur", def: "Créateur de contenu suivi par une communauté, qui peut présenter des produits.", example: "Un compte TikTok sur les chats qui teste ta fontaine.", tip: "Les petits créateurs très proches de leur communauté sont souvent plus accessibles.", related: ["UGC", "Collaboration commerciale"] },
  { term: "Collaboration commerciale", def: "Partenariat où un créateur présente un produit contre rémunération ou cadeau.", example: "Tu envoies ton produit à un créateur qui en parle dans une vidéo.", tip: "La collaboration doit être clairement indiquée au public.", related: ["Influenceur", "UGC"] },
  { term: "Accroche", def: "Les premières secondes d'une vidéo ou la première phrase d'un texte, qui donnent envie de continuer.", example: "« Ton chat ne boit pas assez ? Regarde ça. »", tip: "Montre le problème ou le résultat dès la première seconde.", related: ["Vidéo courte", "Copywriting"] },
  { term: "Vidéo courte", def: "Vidéo de quelques secondes à une minute, publiée sur TikTok, Reels ou Shorts.", example: "Un avant / après de ton produit en 15 secondes.", tip: "Publie régulièrement et teste plusieurs accroches.", related: ["Accroche", "TikTok"] },
  { term: "TikTok", def: "Réseau social de vidéos courtes très utilisé pour faire découvrir des produits.", example: "Une vidéo qui montre ton produit en action dans ta chambre.", tip: "Mets le lien de ta boutique dans ta bio.", related: ["Vidéo courte", "Accroche"] },
  { term: "Copywriting", def: "Art d'écrire des textes qui donnent envie d'agir : acheter, s'inscrire, cliquer.", example: "« Une chambre cosy en 10 secondes, sans travaux. »", tip: "Écris simplement, comme tu parlerais à un ami.", related: ["Description produit", "Accroche"] },
  { term: "Call to action", def: "Bouton ou phrase qui invite à faire une action précise.", example: "« Ajouter au panier » ou « Voir l'aperçu gratuit ».", tip: "Un seul appel à l'action principal par écran.", related: ["Copywriting", "Taux de conversion"] },
  { term: "Landing page", def: "Page conçue pour une seule action, souvent liée à une campagne ou une publicité.", example: "Une page dédiée à ton produit phare, avec un seul bouton d'achat.", tip: "Garde le message cohérent avec la vidéo ou la pub qui y mène.", related: ["Call to action", "Taux de conversion"] },
  { term: "Page d'accueil", def: "Première page de la boutique, qui présente ce que tu vends et donne envie d'aller plus loin.", example: "Une grande photo, une phrase claire et un bouton vers ton produit.", tip: "Le visiteur doit comprendre ce que tu vends en quelques secondes.", related: ["Boutique en ligne", "Call to action"] },
  { term: "Niche", def: "Petit marché précis, avec un public aux besoins communs.", example: "Les accessoires pour chats d'appartement.", tip: "Une niche claire aide à parler directement à tes clients.", related: ["Persona", "Produit gagnant"] },
  { term: "Persona", def: "Portrait du client idéal : âge, habitudes, besoins, problèmes.", example: "« Léa, 24 ans, vit en appartement avec son chat et travaille à distance. »", tip: "Écris tes textes en pensant à cette personne.", related: ["Niche", "Copywriting"] },
  { term: "Produit gagnant", def: "Expression utilisée pour un produit qui se vend bien en ligne, souvent parce qu'il règle un problème et se montre bien en vidéo.", example: "Un produit original qui fait réagir dans les vidéos.", tip: "Aucun produit n'est gagnant à coup sûr : teste avant d'investir.", related: ["Niche", "Dropshipping"] },
  { term: "Marque", def: "Nom, identité visuelle et promesse qui rendent une boutique reconnaissable.", example: "Un nom court, deux couleurs et un ton de voix cohérent.", tip: "Une marque cohérente inspire plus confiance qu'une boutique générique.", related: ["Logo", "Nom de domaine"] },
  { term: "Logo", def: "Symbole ou nom stylisé qui identifie une marque.", example: "Le nom de ta boutique écrit dans une belle police.", tip: "Un logo simple et lisible en petit suffit pour démarrer.", related: ["Marque"] },
  { term: "Nom de domaine", def: "Adresse internet de ta boutique, par exemple maboutique.fr.", example: "Une adresse à ton nom au lieu de l'adresse gratuite de la plateforme.", tip: "Vérifie que le nom n'appartient pas à une marque déposée.", related: ["Marque", "Boutique en ligne"] },
  { term: "Boutique généraliste", def: "Boutique qui vend des produits très différents, sans thème commun.", example: "Une lampe, un jouet pour chien et une montre sur le même site.", tip: "Une boutique de marque autour d'un univers inspire généralement plus confiance.", related: ["Niche", "Marque"] },
  { term: "Print on demand", def: "Impression à la demande : un imprimeur fabrique le produit personnalisé seulement quand un client commande.", example: "Des t-shirts avec tes designs, imprimés à chaque commande.", tip: "N'utilise jamais de logos ou d'images qui ne t'appartiennent pas.", related: ["Dropshipping", "Fournisseur"] },
  { term: "Produit numérique", def: "Produit qui se télécharge, sans envoi physique : guide, modèle, fichier.", example: "Un planning imprimable vendu en PDF.", tip: "Mets clairement en avant ce que contient le fichier avant l'achat.", related: ["Boutique en ligne"] },
  { term: "Précommande", def: "Vente d'un produit avant qu'il soit disponible, avec une date de livraison annoncée.", example: "Tu prends les commandes d'un nouveau modèle livré le mois prochain.", tip: "Annonce une date réaliste et préviens en cas de retard.", related: ["Délai de livraison", "Stock"] },
  { term: "Chargeback", def: "Contestation d'un paiement par un client auprès de sa banque, qui peut entraîner un remboursement forcé.", example: "Un client conteste un achat car son colis n'est jamais arrivé.", tip: "Des délais clairs et un service client réactif réduisent les contestations.", related: ["Délai de livraison", "Service client"] },
  { term: "Service client", def: "Façon dont la boutique répond aux questions et aux problèmes des clients.", example: "Répondre à un e-mail sur un retard de colis dans la journée.", tip: "Une réponse rapide et polie rassure même quand il y a un problème.", related: ["Avis clients", "Chargeback"] },
  { term: "FAQ", def: "Foire aux questions : liste des questions fréquentes avec leurs réponses.", example: "« Combien de temps prend la livraison ? »", tip: "Ajoute les questions que tes clients te posent vraiment.", related: ["Fiche produit", "Service client"] },
  { term: "Taux de rebond", def: "Part des visiteurs qui quittent le site après avoir vu une seule page.", example: "Un visiteur arrive sur l'accueil et repart aussitôt.", tip: "Une page d'accueil claire et rapide aide à le réduire.", related: ["Visiteur", "Page d'accueil"] },
  { term: "Responsive", def: "Se dit d'un site qui s'adapte à toutes les tailles d'écran : téléphone, tablette, ordinateur.", example: "Ta boutique s'affiche correctement sur un iPhone.", tip: "Teste toujours ta boutique sur ton téléphone avant de la publier.", related: ["Thème Shopify"] },
  { term: "A/B test", def: "Test qui compare deux versions d'un élément pour voir laquelle fonctionne le mieux.", example: "Deux titres de fiche produit montrés à des visiteurs différents.", tip: "Ne change qu'un élément à la fois pour savoir ce qui a fait la différence.", related: ["Taux de conversion"] },
  { term: "Saisonnalité", def: "Variation des ventes selon les périodes de l'année.", example: "Les guirlandes solaires se vendent surtout au printemps et en été.", tip: "Prépare ta boutique quelques semaines avant la saison de ton produit.", related: ["Black Friday", "Produit gagnant"] },
  { term: "Black Friday", def: "Période de promotions de fin novembre, très suivie par les acheteurs en ligne.", example: "Une vraie réduction sur ton produit pendant quelques jours.", tip: "Tes réductions doivent être réelles, calculées sur ton prix habituel.", related: ["Saisonnalité", "Prix barré"] },
  { term: "E-commerce", def: "Commerce en ligne : vente de produits ou de services sur internet.", example: "Une boutique Shopify qui vend des accessoires pour chats.", tip: "Commence petit, avec un produit, et améliore ta boutique au fil des retours.", related: ["Boutique en ligne", "Dropshipping"] },
  { term: "Marketplace", def: "Plateforme où plusieurs vendeurs proposent leurs produits au même endroit.", example: "Vendre sur une grande plateforme en plus de ta propre boutique.", tip: "Une marketplace apporte du trafic, ta boutique te donne le contrôle de ta marque.", related: ["Boutique en ligne", "Marque"] },
  { term: "Catalogue", def: "Ensemble des produits proposés par une boutique.", example: "Ta boutique propose 3 produits autour du sommeil de bébé.", tip: "Au début, un petit catalogue cohérent vaut mieux qu'un grand catalogue en vrac.", related: ["Collection", "Niche"] },
  { term: "Collection", def: "Groupe de produits rangés ensemble dans une boutique, par thème ou par usage.", example: "Une collection « Idées cadeaux de Noël ».", tip: "Des collections claires aident les visiteurs à trouver vite ce qu'ils cherchent.", related: ["Catalogue", "Shopify"] },
  { term: "Variante produit", def: "Version d'un même produit qui change par la taille, la couleur ou une option.", example: "Un harnais pour chien en tailles S, M et L.", tip: "Chaque variante doit avoir sa photo et un stock bien suivi.", related: ["Fiche produit", "SKU"] },
  { term: "SKU", def: "Référence unique attribuée à chaque produit ou variante pour suivre le stock.", example: "HARNAIS-M-NOIR pour le harnais taille M noir.", tip: "Des références claires évitent les erreurs de commande.", related: ["Variante produit", "Stock"] },
  { term: "Frais de port", def: "Somme payée pour l'envoi d'une commande, par le client ou par le vendeur.", example: "4,90 € de livraison, offerte dès 2 produits.", tip: "Affiche-les dès la fiche produit pour éviter les abandons de panier.", related: ["Délai de livraison", "Panier abandonné"] },
  { term: "Expédition", def: "Étape où la commande est emballée et confiée au transporteur.", example: "La commande part de l'entrepôt avec un numéro de suivi.", tip: "Préviens ton client quand son colis est expédié.", related: ["Numéro de suivi", "Logistique"] },
  { term: "Logistique", def: "Organisation du stockage, de la préparation et de l'envoi des commandes.", example: "Choisir qui stocke, emballe et envoie tes produits.", tip: "En dropshipping, la logistique dépend de ton fournisseur : choisis-le avec soin.", related: ["Entrepôt", "Expédition"] },
  { term: "Entrepôt", def: "Lieu où sont stockés les produits avant leur envoi.", example: "Un fournisseur avec un entrepôt en Europe livre souvent plus vite.", tip: "Demande à ton fournisseur d'où partent réellement les colis.", related: ["Logistique", "Délai de livraison"] },
  { term: "Délai de préparation", def: "Temps entre la commande et l'expédition du colis.", example: "Le fournisseur prépare la commande en 2 jours avant de l'envoyer.", tip: "Ajoute-le au temps de transport quand tu annonces un délai.", related: ["Délai de livraison", "Expédition"] },
  { term: "Point relais", def: "Commerce partenaire où le client vient récupérer son colis.", example: "Le client choisit une livraison dans un relais près de chez lui.", tip: "Proposer le point relais peut rassurer ceux qui ne sont pas chez eux en journée.", related: ["Frais de port", "Expédition"] },
  { term: "Colis perdu", def: "Colis qui n'arrive jamais à destination pendant le transport.", example: "Le suivi ne bouge plus depuis plusieurs semaines.", tip: "Prévois une petite réserve d'argent pour renvoyer ou rembourser.", related: ["Numéro de suivi", "Service client"] },
  { term: "Douane", def: "Contrôle des marchandises qui entrent dans un pays, qui peut entraîner des taxes.", example: "Un colis venant de l'extérieur de l'Union européenne peut être soumis à la TVA à l'importation.", tip: "Renseigne-toi sur les frais d'importation pour ne pas surprendre ton client.", related: ["TVA", "Fournisseur"] },
  { term: "TVA", def: "Taxe sur la valeur ajoutée, incluse dans le prix payé par le consommateur.", example: "Un prix affiché TTC inclut la TVA.", tip: "Les règles dépendent de ton statut : en micro-entreprise, une franchise de TVA existe sous certains seuils. Vérifie sur les sites officiels.", related: ["Micro-entreprise", "Facture"] },
  { term: "Facture", def: "Document qui détaille une vente : produits, prix, taxes, date et identité des parties.", example: "La facture envoyée automatiquement après la commande.", tip: "Garde toutes tes factures d'achat et de vente.", related: ["TVA", "Micro-entreprise"] },
  { term: "Garantie légale de conformité", def: "Protection qui oblige le vendeur à réparer, remplacer ou rembourser un produit défectueux ou non conforme. En France, elle dure en principe 2 ans pour un bien neuf.", example: "Une lampe qui ne s'allume plus après un mois.", tip: "Mentionne-la dans tes CGV et traite les demandes rapidement.", related: ["CGV", "Politique de retour"] },
  { term: "Remboursement", def: "Restitution de l'argent payé par le client.", example: "Un client se rétracte et reçoit son argent sous 14 jours.", tip: "Indique clairement le délai et le moyen de remboursement.", related: ["Droit de rétractation", "Politique de retour"] },
  { term: "Politique de confidentialité", def: "Page qui explique quelles données personnelles la boutique collecte et comment elle les utilise.", example: "Adresse e-mail utilisée pour envoyer la confirmation de commande.", tip: "Elle est indispensable dès que tu collectes des données.", related: ["RGPD", "Cookie"] },
  { term: "RGPD", def: "Règlement européen qui protège les données personnelles des personnes.", example: "Demander l'accord avant d'envoyer une newsletter.", tip: "Ne collecte que les données utiles et explique pourquoi.", related: ["Politique de confidentialité", "Cookie"] },
  { term: "Cookie", def: "Petit fichier enregistré par un site dans le navigateur du visiteur.", example: "Un cookie qui garde le contenu du panier.", tip: "Certains cookies demandent l'accord du visiteur avant d'être utilisés.", related: ["RGPD", "Pixel de suivi"] },
  { term: "Pixel de suivi", def: "Code ajouté au site pour mesurer les actions des visiteurs venus d'une publicité.", example: "Le pixel indique qu'une personne venue d'une pub a acheté.", tip: "Respecte le consentement des visiteurs.", related: ["Publicité Meta", "Cookie"] },
  { term: "Passerelle de paiement", def: "Service qui fait le lien entre la boutique et la banque pour encaisser les paiements.", example: "Le service qui traite les paiements par carte sur ta boutique.", tip: "Choisis une solution reconnue, qui rassure les clients.", related: ["Moyen de paiement", "Checkout"] },
  { term: "Frais de transaction", def: "Frais prélevés sur chaque paiement par la plateforme ou le service de paiement.", example: "Un petit pourcentage retenu sur chaque vente.", tip: "Intègre-les dans le calcul de ta marge.", related: ["Marge", "Passerelle de paiement"] },
  { term: "3D Secure", def: "Vérification supplémentaire demandée lors d'un paiement par carte, souvent par l'application de la banque.", example: "Le client valide son paiement dans l'application de sa banque.", tip: "Elle protège contre la fraude ; explique-la si des clients s'inquiètent.", related: ["Moyen de paiement", "Fraude au paiement"] },
  { term: "Fraude au paiement", def: "Utilisation frauduleuse d'un moyen de paiement pour acheter.", example: "Une commande passée avec une carte volée.", tip: "Méfie-toi des grosses commandes inhabituelles et vérifie avant d'expédier.", related: ["3D Secure", "Chargeback"] },
  { term: "Hébergement", def: "Service qui stocke un site internet et le rend accessible en ligne.", example: "Avec Shopify, l'hébergement est inclus.", tip: "Un site rapide aide la conversion et le SEO.", related: ["Shopify", "Nom de domaine"] },
  { term: "HTTPS", def: "Version sécurisée de l'adresse d'un site, avec un cadenas dans le navigateur.", example: "https://maboutique.fr.", tip: "Indispensable pour une boutique : les visiteurs le remarquent.", related: ["Hébergement", "Nom de domaine"] },
  { term: "Balise title", def: "Titre d'une page affiché dans les résultats de Google et dans l'onglet du navigateur.", example: "« Lampe coucher de soleil pour chambre | MaBoutique ».", tip: "Mets le mot-clé principal au début, en restant lisible.", related: ["SEO", "Méta-description"] },
  { term: "Méta-description", def: "Court texte qui résume une page et peut s'afficher sous le titre dans Google.", example: "« Une lumière douce pour ta chambre, livrée en France. »", tip: "Écris-la comme une petite publicité qui donne envie de cliquer.", related: ["Balise title", "SEO"] },
  { term: "Backlink", def: "Lien d'un autre site qui pointe vers le tien.", example: "Un blog de déco qui cite ta boutique.", tip: "Quelques liens de sites sérieux valent mieux que beaucoup de liens douteux.", related: ["SEO", "Trafic"] },
  { term: "Analytics", def: "Outils qui mesurent les visites, les sources de trafic et les actions sur un site.", example: "Voir que la moitié de tes visiteurs viennent de TikTok.", tip: "Regarde tes chiffres chaque semaine pour décider quoi améliorer.", related: ["Trafic", "Taux de conversion"] },
  { term: "CTR", def: "Taux de clic : part des personnes qui cliquent après avoir vu un lien ou une publicité.", example: "10 clics pour 1 000 affichages, soit 1 %.", tip: "Une meilleure accroche ou image améliore souvent le CTR.", related: ["CPC", "Accroche"] },
  { term: "CPC", def: "Coût par clic : prix payé en publicité pour chaque clic.", example: "20 € de pub pour 40 clics, soit 0,50 € par clic.", tip: "Un CPC bas ne sert à rien si les visiteurs n'achètent pas.", related: ["CTR", "Coût d'acquisition"] },
  { term: "CPM", def: "Coût pour mille affichages d'une publicité.", example: "Payer un certain montant chaque fois que la pub est vue 1 000 fois.", tip: "Compare-le avec tes ventes réelles, pas seulement avec les vues.", related: ["CPC", "Publicité Meta"] },
  { term: "ROAS", def: "Retour sur dépenses publicitaires : chiffre d'affaires généré divisé par le budget publicitaire.", example: "300 € de ventes pour 100 € de pub : ROAS de 3.", tip: "Vérifie que ton ROAS couvre aussi tes autres frais, pas seulement la pub.", related: ["ROI", "Coût d'acquisition"] },
  { term: "ROI", def: "Retour sur investissement : ce qu'une dépense rapporte par rapport à ce qu'elle a coûté.", example: "Un investissement de 100 € qui rapporte 150 € de bénéfice.", tip: "Raisonne en bénéfice, pas en chiffre d'affaires.", related: ["ROAS", "Bénéfice"] },
  { term: "Audience similaire", def: "Public publicitaire qui ressemble à tes clients existants.", example: "Montrer ta pub à des personnes proches de tes acheteurs.", tip: "Elle marche mieux quand tu as déjà quelques clients.", related: ["Publicité Meta", "Persona"] },
  { term: "Tunnel de vente", def: "Chemin suivi par un visiteur, de la découverte de la boutique jusqu'à l'achat.", example: "Vidéo TikTok, puis fiche produit, panier et paiement.", tip: "Repère l'étape où les gens partent et améliore-la en premier.", related: ["Taux de conversion", "Parcours client"] },
  { term: "Parcours client", def: "Ensemble des étapes et contacts d'un client avec la boutique, avant et après l'achat.", example: "Découverte, achat, livraison, avis, nouvel achat.", tip: "Chaque étape peut rassurer ou faire fuir : soigne-les toutes.", related: ["Tunnel de vente", "Service client"] },
  { term: "Objection", def: "Raison qui fait hésiter un client avant d'acheter.", example: "« Et si ça ne me va pas ? » ou « La livraison sera-t-elle longue ? ».", tip: "Réponds aux objections dans la fiche produit et la FAQ.", related: ["FAQ", "Réassurance"] },
  { term: "Réassurance", def: "Éléments qui rassurent le client au moment d'acheter : paiement sécurisé, délais, contact, avis.", example: "« Paiement sécurisé · Livraison suivie · Réponse sous 24 h ».", tip: "Place-les près du bouton d'achat.", related: ["Objection", "Avis clients"] },
  { term: "Proposition de valeur", def: "Phrase qui résume ce que ton produit apporte et pourquoi le choisir.", example: "« Une chambre cosy en 10 secondes, sans travaux. »", tip: "Elle doit se comprendre en un coup d'œil.", related: ["Copywriting", "Positionnement"] },
  { term: "Positionnement", def: "Place que ta marque veut occuper dans l'esprit des clients : prix, style, public.", example: "Accessoires premium pour chats d'appartement.", tip: "Un positionnement clair aide à choisir tes produits et tes prix.", related: ["Marque", "Proposition de valeur"] },
  { term: "Identité visuelle", def: "Ensemble des éléments graphiques d'une marque : logo, couleurs, polices, style des photos.", example: "Deux couleurs et une police utilisées partout.", tip: "La cohérence compte plus que la perfection.", related: ["Logo", "Marque"] },
  { term: "Storytelling", def: "Façon de présenter une marque ou un produit à travers une histoire.", example: "« J'ai créé cette boutique après avoir cherché une veilleuse douce pour mon neveu. »", tip: "Raconte une histoire vraie : les histoires inventées se repèrent.", related: ["Copywriting", "Marque"] },
  { term: "Packaging", def: "Emballage du produit, qui le protège et participe à l'image de la marque.", example: "Une jolie boîte avec un petit mot à l'intérieur.", tip: "Un packaging soigné donne envie de partager le déballage.", related: ["Marque", "UGC"] },
  { term: "Marque blanche", def: "Produit fabriqué par un fournisseur et vendu sous le nom d'une autre marque.", example: "Une gourde fabriquée par un fournisseur avec ton logo.", tip: "Vérifie les quantités minimales et la qualité avant de te lancer.", related: ["Fournisseur", "Marque"] },
  { term: "Sourcing", def: "Recherche et sélection des fournisseurs et des produits à vendre.", example: "Comparer trois fournisseurs pour le même produit.", tip: "Compare la qualité, les délais et la réactivité, pas seulement le prix.", related: ["Fournisseur", "Échantillon"] },
  { term: "Prospect", def: "Personne qui pourrait devenir cliente, mais qui n'a pas encore acheté.", example: "Un visiteur inscrit à ta newsletter.", tip: "Apporte-lui de la valeur avant de lui demander d'acheter.", related: ["Newsletter", "Tunnel de vente"] },
  { term: "Fidélisation", def: "Actions pour que les clients reviennent acheter.", example: "Un e-mail utile quelques semaines après l'achat.", tip: "Un client satisfait coûte généralement moins cher à faire revenir qu'un nouveau client à trouver.", related: ["Programme de fidélité", "Rétention client"] },
  { term: "Rétention client", def: "Capacité d'une boutique à garder ses clients dans le temps.", example: "Des clients qui rachètent des recharges chaque mois.", tip: "Les produits consommables favorisent les achats répétés.", related: ["Fidélisation", "Panier moyen"] },
  { term: "Programme de fidélité", def: "Système qui récompense les clients qui achètent régulièrement.", example: "Des points cumulés à chaque achat.", tip: "Garde-le simple pour que les clients le comprennent.", related: ["Fidélisation", "Code promo"] },
  { term: "Carte cadeau", def: "Montant prépayé que le client offre à quelqu'un pour acheter sur la boutique.", example: "Une carte cadeau de 30 € offerte pour un anniversaire.", tip: "Pratique pendant les fêtes pour ceux qui hésitent sur le cadeau.", related: ["Saisonnalité", "Panier moyen"] },
  { term: "Liste de souhaits", def: "Liste où le visiteur garde les produits qui l'intéressent pour plus tard.", example: "Un cœur sur la fiche produit pour l'enregistrer.", tip: "Elle peut aider à relancer les visiteurs indécis, avec leur accord.", related: ["Panier abandonné", "E-mail marketing"] },
  { term: "Affiliation", def: "Système où un partenaire touche une commission quand il apporte une vente.", example: "Un créateur partage son lien et reçoit une part de chaque vente.", tip: "Indique clairement au public qu'il s'agit d'un lien affilié.", related: ["Influenceur", "Collaboration commerciale"] },
  { term: "Ambassadeur", def: "Client ou créateur qui recommande régulièrement une marque.", example: "Une cliente qui partage ses photos avec ton produit.", tip: "Remercie et valorise tes premiers ambassadeurs.", related: ["UGC", "Affiliation"] },
  { term: "Algorithme", def: "Règles automatiques qui décident quels contenus un réseau social montre à chaque personne.", example: "TikTok montre ta vidéo à plus de monde si elle est regardée jusqu'au bout.", tip: "Concentre-toi sur des vidéos qu'on a envie de regarder en entier.", related: ["TikTok", "Engagement"] },
  { term: "Engagement", def: "Réactions du public à un contenu : likes, commentaires, partages, enregistrements.", example: "Une vidéo commentée et partagée par beaucoup de personnes.", tip: "Réponds aux commentaires : c'est souvent là que naissent les premières ventes.", related: ["Algorithme", "Communauté"] },
  { term: "Communauté", def: "Ensemble de personnes qui suivent une marque et interagissent avec elle.", example: "Les abonnés qui commentent chacune de tes vidéos.", tip: "Une petite communauté fidèle vaut mieux qu'un grand public indifférent.", related: ["Engagement", "Ambassadeur"] },
  { term: "Hashtag", def: "Mot précédé du signe # qui classe un contenu par thème sur les réseaux sociaux.", example: "#decochambre sous une vidéo de lampe.", tip: "Utilise quelques hashtags précis plutôt que beaucoup de hashtags généraux.", related: ["TikTok", "Algorithme"] },
  { term: "Reels", def: "Format de vidéos courtes sur Instagram et Facebook.", example: "Un Reel de 15 secondes qui montre ton produit en action.", tip: "Réutilise tes meilleures vidéos TikTok en Reels.", related: ["Vidéo courte", "TikTok"] },
  { term: "Merchandising", def: "Façon de présenter les produits pour donner envie d'acheter.", example: "Mettre ton produit phare en premier sur la page d'accueil.", tip: "Mets en avant ce qui se vend le mieux.", related: ["Page d'accueil", "Collection"] },
  { term: "Bannière", def: "Grande image en haut d'une page qui présente une offre ou l'univers de la boutique.", example: "Une photo de chambre cosy avec « Nouvelle collection ».", tip: "Un message court et une seule action.", related: ["Page d'accueil", "Call to action"] },
  { term: "Mobile first", def: "Façon de concevoir un site en pensant d'abord au téléphone.", example: "Le bouton d'achat visible sans faire défiler sur un téléphone.", tip: "Teste chaque page sur ton téléphone avant de publier.", related: ["Responsive", "Page d'accueil"] },
  { term: "Abonnement", def: "Paiement régulier, chaque mois ou chaque année, pour un produit ou un service.", example: "Un abonnement mensuel à une plateforme de boutique.", tip: "Note tous tes abonnements : ils s'additionnent vite.", related: ["Shopify", "Bénéfice"] },
  { term: "API", def: "Moyen technique qui permet à deux logiciels d'échanger des informations.", example: "L'application de dropshipping qui récupère les commandes de ta boutique.", tip: "Tu n'as pas besoin de coder : les applications s'en occupent pour toi.", related: ["Application Shopify", "Shopify"] },
  { term: "Lead magnet", def: "Contenu offert en échange d'une adresse e-mail.", example: "Un guide gratuit contre une inscription à la newsletter.", tip: "Il doit être vraiment utile pour la personne.", related: ["Newsletter", "Prospect"] },
  // Passage SEO du 28 novembre (nuit)
  { term: "Shopify Payments", def: "Solution de paiement intégrée à Shopify, qui permet d'accepter les cartes bancaires et les paiements rapides sans passer par un autre prestataire, dans les pays où elle est disponible.", example: "Tu l'actives dans les réglages de paiement et tes clients peuvent payer par carte ou avec Apple Pay.", tip: "Vérifie les frais de transaction à jour dans les réglages : ils comptent dans ta marge.", related: ["Passerelle de paiement", "Frais de transaction", "Moyen de paiement"] },
  { term: "Paiement fractionné", def: "Possibilité pour le client de payer un achat en plusieurs fois, proposée par certaines solutions de paiement.", example: "Un client règle son achat en trois échéances au lieu d'une.", tip: "Affiche les conditions clairement et ne pousse pas les clients à acheter au-dessus de leurs moyens.", related: ["Moyen de paiement", "Panier moyen"] },
  { term: "Commande test", def: "Commande passée par le vendeur lui-même pour vérifier que le paiement, les e-mails et la livraison fonctionnent avant l'ouverture.", example: "Avant de lancer ta boutique, tu passes une commande test pour voir l'e-mail de confirmation.", tip: "Annule ou rembourse la commande test ensuite pour ne pas fausser tes chiffres.", related: ["Checkout", "Boutique en ligne"] },
  { term: "Fulfillment", def: "Ensemble des étapes qui suivent une commande : préparation, emballage, expédition et parfois gestion des retours.", example: "En dropshipping, le fulfillment est fait par ton fournisseur.", tip: "Vérifie le délai de préparation de ton fournisseur, pas seulement le délai de transport.", related: ["Logistique", "Expédition", "Délai de préparation"] },
  { term: "Taux d'abandon de panier", def: "Part des visiteurs qui ajoutent un produit au panier mais ne terminent pas leur achat.", example: "Sur 10 paniers créés, 7 ne sont pas payés : le taux d'abandon est de 70 %.", tip: "Affiche les frais de livraison tôt : les mauvaises surprises au paiement font abandonner.", related: ["Panier abandonné", "Checkout", "Taux de conversion"] },
  { term: "Valeur vie client", def: "Somme totale qu'un client dépense dans ta boutique pendant toute la durée de votre relation.", example: "Un client qui commande trois fois dans l'année a une valeur bien plus grande que sa première commande.", tip: "Comparer cette valeur au coût d'acquisition aide à savoir combien tu peux dépenser pour trouver un client.", related: ["Coût d'acquisition", "Fidélisation", "Rétention client"] },
  { term: "Produit d'appel", def: "Produit au prix attractif qui fait venir les clients, qui achètent ensuite d'autres produits avec plus de marge.", example: "Un petit accessoire pas cher en avant sur ta page d'accueil, qui mène vers les coffrets.", tip: "Même un produit d'appel ne doit pas être vendu à perte sans calcul.", related: ["Cross-sell", "Panier moyen", "Marge"] },
  { term: "Personnalisation", def: "Option qui permet au client d'ajouter un prénom, une date ou un texte sur le produit qu'il achète.", example: "Un collier gravé avec le prénom de la personne à qui on l'offre.", tip: "Fais relire au client ce qu'il a tapé avant de valider : une faute gravée ne se corrige pas.", related: ["Variante produit", "Print on demand"] },
  { term: "Page collection", def: "Page de la boutique qui regroupe plusieurs produits liés, par exemple par catégorie ou par thème.", example: "Une page « Idées cadeaux de Noël » qui rassemble tes produits à offrir.", tip: "Écris un court texte en haut de la page : il aide les visiteurs et le référencement.", related: ["Collection", "Catalogue", "SEO"] },
  { term: "Bandeau d'annonce", def: "Petite barre en haut de la boutique qui affiche une information importante à tous les visiteurs.", example: "« Livraison offerte dès 40 € » ou « Commandez avant le 18 décembre pour Noël ».", tip: "Une seule information à la fois, et toujours vraie.", related: ["Réassurance", "Frais de port"] },
  // Passage SEO du 28 novembre
  { term: "Google Merchant Center", def: "Outil de Google où l'on envoie les informations de ses produits pour qu'ils puissent apparaître dans Google Shopping.", example: "Ta boutique envoie chaque nuit ses produits et prix à Merchant Center.", tip: "Corrige vite les produits refusés : la raison est indiquée dans l'outil.", related: ["SEO", "Catalogue"] },
  { term: "Redirection 301", def: "Règle qui envoie automatiquement les visiteurs et les moteurs de recherche d'une ancienne adresse vers une nouvelle, de façon permanente.", example: "Tu renommes un produit et l'ancienne adresse renvoie vers la nouvelle page.", tip: "Fais-la à chaque changement d'adresse pour ne pas perdre les visites de Google.", related: ["SEO", "Indexation"] },
  { term: "Seuil de rentabilité", def: "Nombre de ventes ou montant de chiffre d'affaires à partir duquel tes recettes couvrent tous tes frais.", example: "Avec 50 € de frais fixes et 10 € de marge par vente, il faut 5 ventes par mois pour ne rien perdre.", tip: "Calcule-le avant de lancer une publicité.", related: ["Marge", "Bénéfice", "Chiffre d'affaires"] },
  { term: "Taux de marge", def: "Part de la marge dans le prix de vente, exprimée en pourcentage.", example: "Un produit vendu 40 € hors taxes qui te laisse 16 € a un taux de marge de 40 %.", tip: "Compare-le entre tes produits pour savoir lesquels mettre en avant.", related: ["Marge", "Prix de vente"] },
  { term: "Médiateur de la consommation", def: "Personne ou organisme indépendant qui aide à régler à l'amiable un litige entre un consommateur et un professionnel.", example: "Un client mécontent peut saisir le médiateur indiqué dans tes CGV.", tip: "Choisis ton médiateur sur la liste officielle et mentionne-le dans tes CGV.", related: ["CGV", "Service client"] },
  { term: "Emballage neutre", def: "Colis sans logo, prix ni publicité du fournisseur, pour que le client ne reçoive que ce qui vient de ta marque.", example: "Ton fournisseur envoie le produit dans un carton blanc sans facture.", tip: "Demande-le au fournisseur avant ta première commande.", related: ["Dropshipping", "Packaging", "Fournisseur"] },
  { term: "Code-barres EAN", def: "Code à barres standard qui identifie un produit de façon unique dans le commerce.", example: "Certaines places de marché demandent un EAN pour chaque produit.", tip: "Achète les codes auprès de l'organisme officiel plutôt que sur des sites douteux.", related: ["SKU", "Marketplace"] },
  { term: "Vitesse de chargement", def: "Temps nécessaire pour qu'une page s'affiche et devienne utilisable.", example: "Une fiche produit avec des images trop lourdes met longtemps à s'afficher sur téléphone.", tip: "Compresse tes images et limite le nombre d'applications.", related: ["Responsive", "Taux de rebond", "SEO"] },
  { term: "Garantie commerciale", def: "Garantie supplémentaire et facultative proposée par le vendeur, en plus des garanties légales.", example: "« Garantie 3 ans » offerte par une marque en plus de la garantie légale.", tip: "Elle ne remplace jamais la garantie légale de conformité.", related: ["Garantie légale de conformité", "CGV"] },
  { term: "Fiche de taille", def: "Tableau qui indique les mesures de chaque taille d'un vêtement ou d'un accessoire.", example: "Un tableau tour de poitrine, longueur et taille correspondante pour un pull.", tip: "Donne les mesures en centimètres et explique comment se mesurer.", related: ["Variante produit", "Politique de retour"] },
];

export const termSlug = (t: string) =>
  t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/['\u2019/]/g, "-").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
